#!/usr/bin/env python3
"""Render measured representative results; full precise data remains in CSV/JSON."""
import argparse,json
from pathlib import Path
HERE=Path(__file__).resolve().parent
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--final',action='store_true');a=p.parse_args()
data=json.loads((HERE/'summary/summary.json').read_text());rows=data['measurements']
def get(name,implementation='native'):
    return next(x for x in rows if x['name']==name and x['implementation']==implementation)
def count(n):return f'{n:,.0f}'
def table(headers,items):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,item))+' |' for item in items])
lines=['# Crypto benchmark results','',('Final integrated artifact measurements.' if a.final else 'Validated development measurements; the consolidated final-artifact pass is pending.'),'',f"**{data['passed']} of {data['cases']} implementation/workload combinations passed**, each with three fresh-canister trials. The remaining baseline fails the official BLAKE3 16 KiB output and contributes no ratio. All successful selected measurements were checked against independent exact output bytes. Full numeric data, failure status, semantics and stage provenance are in [measurements.csv](summary/measurements.csv), [comparisons.csv](summary/comparisons.csv) and [summary.json](summary/summary.json).",'', 'The ratio below is Mops instructions divided by native instructions. Values below 1 mean the native API costs more. Canister Wasm size and allocation are measured separately; lower instruction counts do not imply smaller Wasm. See [methodology and reproduction](README.md).','', '## Representative primitives','']
choices=[('BLAKE3, 1 KiB','blake3-1024','native','mops-blake3'),('BLAKE3 keyed, 1 KiB','blake3-keyed-1024','native','mops-blake3'),('SHA512, 1 KiB','sha512-1024','native','mops-sha2'),('RIPEMD160, 32 bytes','ripemd160-32','native','mops-bitcoin'),('HMAC-SHA512, 64 bytes','hmac-sha512-64','native','mops-bitcoin'),('HMAC-SHA512 prepared, 64 bytes','hmac-sha512-prepared-64','native','mops-bitcoin'),('Base58 encode, 82 bytes','base58-encode-82','native','mops-bitcoin'),('Bech32m decode, 53 values','bech32m-decode-53','native','mops-bitcoin'),('secp256k1 ECDSA verify','secp256k1_verify_ecdsa_fast','fast','ecdsa'),('P256 ECDSA verify','p256_verify_ecdsa_fast','fast','ecdsa'),('BLS map to G1','bls12_381_map_to_g1_fast','fast','bls12-381'),('BLS map to G2','bls12_381_map_to_g2_fast','fast','bls12-381'),('BLS G2 MSM, 128 distinct points','bls12_381_g2_msm_distinct_128_fast','fast','bls12-381')]
items=[]
for label,name,impl,baseline in choices:
    try:n=get(name,impl)
    except StopIteration:continue
    comp=next((x for x in data['comparisons'] if x['name']==name and x['native']==impl and x['baseline']==baseline),None)
    if not comp:continue
    items.append([label,count(comp['native_instructions']),count(comp['baseline_instructions']),f"{comp['instruction_ratio']:.2f}×",f"{count(comp['native_allocated_bytes'])} / {count(comp['baseline_allocated_bytes'])}",f"{comp['native_wasm_bytes']/1024:.1f} / {comp['baseline_wasm_bytes']/1024:.1f}"])
lines+=[table(['Workload','Native instructions','Mops instructions','Ratio','Allocated bytes native / Mops','Canister KiB native / Mops'],items),'','Native curve APIs validate serialized inputs. Mops ECDSA fixtures prepare keys outside measurement. BLS MSM includes native compressed-point/subgroup validation while its Mops baseline starts from trusted in-memory points. These are complete public API comparisons, not isolated arithmetic kernels.','', '## Bitcoin composition','']
choices=[('HASH160 compressed pubkey','bitcoin-hash160-pubkey','native'),('P2PKH validating public API','bitcoin-p2pkh','native'),('P2PKH trusted-byte payload API','bitcoin-p2pkh','native-prevalidated'),('P2WPKH validating public API','bitcoin-p2wpkh','native'),('P2WPKH trusted-byte payload API','bitcoin-p2wpkh','native-prevalidated'),('BIP32 public child + xpub encoding','bitcoin-bip32-child0','native'),('BIP86 account xpub → receive address','bitcoin-bip86-receive-address','native'),('Serialize transaction, 100 inputs','bitcoin-serialize-100-inputs','native'),('Legacy sighashes, all 100 inputs','bitcoin-legacy-all-sign-all-100-inputs','native'),('Taproot sighashes, all 100 inputs','bitcoin-taproot-default-sign-all-100-inputs','native'),('Legacy sighash + ECDSA verify','bitcoin-legacy-sighash-verify-1-input','native')]
items=[]
for label,name,impl in choices:
    comp=next(x for x in data['comparisons'] if x['name']==name and x['native']==impl and x['baseline']=='mops-bitcoin')
    items.append([label,count(comp['native_instructions']),count(comp['baseline_instructions']),f"{comp['instruction_ratio']:.2f}×"])
lines+=[table(['Workflow','Native instructions','Mops instructions','Ratio'],items),'','The validating address APIs are slower because the Mops convenience routines hash bytes without curve validation. The explicit trusted-byte payload rows perform equivalent HASH160 and address encoding without changing the validating API contract. The BIP86 row includes account parsing, two public child derivations, empty-tree TapTweak and Bech32m encoding.','']
# Prepared workloads have different names; preserve their explicit internal comparison.
prepared=[x for x in rows if x['native'] and '100-inputs' in x['name'] and 'cache' in x['name']]
if prepared:
    lines+=['Prepared transaction hashers amortize common hashes across inputs. Cold preparation is included in each measured batch. Mops has no BIP143 implementation to compare.','',table(['Native 100-input workload','Variant','Instructions','Allocated bytes'],[[x['name'],x['implementation'],count(x['instructions_median']),count(x['allocated_bytes_median'])] for x in prepared]),'']
lines+=['## Validation cost and absolute-only APIs','', 'Trusted BLS addition is not equivalent to parsing and subgroup-checking public input. Native G1/G2 addition costs about 28.4M/75.7M instructions; trusted Mops arithmetic costs about 0.42M/0.98M. Including validation and encoding changes the comparison: the retained validated G1 baseline costs about 329M, and G2 about 168M. G2 uses EIP-style uncompressed baseline input versus native compressed input; this wire-format difference remains explicit.','']
absolute=['secp256k1_sign_rfc6979_fast','p256_sign_rfc6979_fast','secp256k1_schnorr_sign_fast','secp256k1_schnorr_verify_fast','bls12_381_verify_ic_valid_fast','bls12_381_verify_ethereum_valid_fast','bls12_381_hash_to_g1_fast','bls12_381_hash_to_g2_fast']
items=[]
for name in absolute:
    try:r=get(name,'fast')
    except StopIteration:continue
    items.append([name,count(r['instructions_median']),count(r['allocated_bytes_median'])])
lines+=[table(['Native operation','Instructions','Allocated bytes'],items),'','Mops ECDSA signing takes a supplied nonce, while native signing uses RFC6979; those costs are not presented as a direct speedup. Schnorr and complete IC/Ethereum BLS verification have no corresponding API in the selected Mops packages. Valid and wrong-message BLS signatures were independently checked.','', '## Optimization experiments','', 'Exact before/after artifact identities and instruction, allocation and Wasm deltas are in [optimizations.json](summary/optimizations.json).','', 'Accepted changes were measured before and after: RIPEMD160 fixed 32-byte hashing cuts roughly 11% from the HASH160-sized kernel; Bech32 reverse-table decoding cuts roughly 3–4% while shrinking its runtime; secp256k1/P256 RFC6979 signing avoids an unused public-key multiplication and saves roughly 46%/45%; BLS windowed MSM saves up to roughly 65% on the retained matrix. Empty-input digest constants reduce BLAKE3, SHA512/SHA384 and RIPEMD160 overhead.','', 'Prepared HMAC keys cut native 64-byte authentication costs by about 36% (SHA256) and 41% (SHA512). Prepared transaction hashing reduces instruction counts by factors of about 27 (BIP143) and 35 (Taproot) across 100 inputs, with cold setup counted.','', 'SHA512 and HMAC compression-unrolling trials were rejected: modest instruction savings did not justify their larger Wasm and maintenance burden. Their frozen experiments remain available under `results/sha512-native-candidate` and `results/hmac-unrolled256-*`; the selected final results retain the pinned RustCrypto kernels.','', '## Correctness findings and retained evidence','', '- Mops BLAKE3 0.1.2 returns the wrong official digest for the 16 KiB patterned input. Its source lacks complete chunk-tree handling. Context-based derivation is also excluded because the package ignores the context. Correct single-chunk and keyed fixtures pass.','- An early benchmark typo added a question mark to the official BLAKE3 key, making it 33 bytes. Native correctly rejected it. The corrected 32-byte fixture supersedes those measurements; this was a harness defect, not a keyed-hash implementation failure.','- Early build/setup failures are retained in their original stage logs, including the missing published BLAKE3 base dependency and two incorrect Bitcoin baseline call adapters. Corrected rows pass all three trials.','- Every selected stage records compiler/RTS and plugin hashes, source snapshots, dependency hashes, Wasm identity and independent output hashes. `source-store.tar.gz` deduplicates exact source bytes; per-stage `source-map.json` files and the restore utility reconstruct them. Executable artifacts remain locally available but are excluded from version control.','']
(HERE/'RESULTS.md').write_text('\n'.join(lines))
print(HERE/'RESULTS.md')
